 static int checks;static final int WORK=64000000;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}interface Attempt{void run()throws Exception;}static void reject(Attempt a,String why)throws Exception{boolean fail=false;try{a.run();}catch(Exception expected){fail=true;}require(fail,why);}
